import sys
sys.setrecursionlimit(10**7)

N, K = 0, 0
fifty, hundred = 0, 0
memo = None
memo2 = None
MOD = 10**9 + 7
comb = None

def solve(t, f, h):
    global memo, fifty, hundred, K
    if f == 0 and h == 0:
        return 0
    if memo[t][f][h] != -1:
        return memo[t][f][h]
    if t == 1:
        if f < fifty:
            res = 1 + solve(0, f + 1, h)
        else:
            res = 1 + solve(0, f, h + 1)
        memo[t][f][h] = res
        return res
    ans = int(1e6)
    for i in range(f + 1):
        if i * 50 > K:
            break
        j = min((K - i * 50) // 100, h)
        totalW = i * 50 + j * 100
        if (fifty - f + i > 0 and totalW > 50) or (hundred - h + j > 1 and totalW > 100) or (i == fifty and j == hundred):
            continue
        ans = min(ans, solve(1, f - i, h - j))
    memo[t][f][h] = ans + 1
    return memo[t][f][h]

def solve2(t, f, h, r):
    global memo2, fifty, hundred, K
    if r == 0 and f == 0 and h == 0:
        return 1
    if r == 0:
        return 0
    if memo2[t][f][h][r] != -1:
        return memo2[t][f][h][r]
    ans = 0
    if t == 1:
        for i in range(fifty - f + 1):
            if i * 50 > K:
                break
            for j in range(hundred - h + 1):
                if i == 0 and j == 0:
                    continue
                totalW = i * 50 + j * 100
                if totalW > K:
                    break
                val = (nCk(fifty - f, i) * nCk(hundred - h, j)) % MOD
                val = (val * solve2(0, f + i, h + j, r - 1)) % MOD
                ans = (ans + val) % MOD
    else:
        for i in range(f + 1):
            if i * 50 > K:
                break
            for j in range(h + 1):
                if i == 0 and j == 0:
                    continue
                totalW = i * 50 + j * 100
                if totalW > K:
                    break
                val = (nCk(f, i) * nCk(h, j)) % MOD
                val = (val * solve2(1, f - i, h - j, r - 1)) % MOD
                ans = (ans + val) % MOD
    memo2[t][f][h][r] = ans
    return ans

def nCk(n, k):
    global comb
    if n < k:
        return 0
    if k == 0 or k == n:
        return 1
    if comb[n][k] != -1:
        return comb[n][k]
    if n - k < k:
        return nCk(n, n - k)
    comb[n][k] = (n * nCk(n - 1, k - 1)) % MOD
    inv_k = pow(k, MOD - 2, MOD)
    return (comb[n][k] * inv_k) % MOD

def pow(x, p):
    result = 1
    base = x
    exp = p
    while exp > 0:
        if exp % 2 == 1:
            result = (result * base)
        base = (base * base)
        exp //= 2
    return result

def main():
    global N, K, fifty, hundred, memo, memo2, comb
    input_data = sys.stdin.read().strip().split()
    N = int(input_data[0])
    K = int(input_data[1])
    vals = list(map(int, input_data[2:]))

    fifty = 0
    hundred = 0
    for v in vals:
        if v == 50:
            fifty += 1
        elif v == 100:
            hundred += 1

    memo = [[[ -1 for _ in range(hundred + 1)] for _ in range(fifty + 1)] for _ in range(2)]
    for i in range(2):
        for j in range(fifty + 1):
            for k in range(hundred + 1):
                memo[i][j][k] = -1

    comb = [[-1 for _ in range(101)] for _ in range(101)]
    for i in range(101):
        for j in range(101):
            comb[i][j] = -1

    min_steps = solve(0, fifty, hundred)
    if min_steps >= 1e6:
        print(-1)
        print(0)
    else:
        memo2 = [[[[ -1 for _ in range(min_steps + 1)] for _ in range(hundred + 1)] for _ in range(fifty + 1)] for _ in range(2)]
        for i in range(2):
            for j in range(fifty + 1):
                for k in range(hundred + 1):
                    for l in range(min_steps + 1):
                        memo2[i][j][k][l] = -1
        print(min_steps)
        print(solve2(0, fifty, hundred, min_steps))

if __name__ == "__main__":
    main()

